/// The id of `--output`, where commands returning a file write it.
pub const OUTPUT: &str = "output";

/// A parameter: positional for path parameters, else a flag.
#[derive(Clone, Copy, Debug)]
pub struct Param {
    pub id: &'static str,
    pub kind: Kind,
    pub positional: bool,
    pub required: bool,
    pub many: bool,
    /// A file to upload, `-` for stdin.
    pub file: bool,
    pub help: &'static str,
    /// The values it accepts, for enums; any when empty.
    pub values: &'static [&'static str],
    /// The help's name of the value (`DATE`), else the kind's.
    pub value_name: &'static str,
    /// The values in range, after the value's name: `1..100`, `>0`.
    pub range: &'static str,
    /// What the API takes when it is not given, for help only: it is not sent.
    pub default: &'static str,
    pub deprecated: bool,
}

impl Param {
    pub const fn flag(id: &'static str, kind: Kind) -> Self {
        Self {
            id,
            kind,
            positional: false,
            required: false,
            many: false,
            file: false,
            help: "",
            values: &[],
            value_name: "",
            range: "",
            default: "",
            deprecated: false,
        }
    }

    /// A required positional argument, as path parameters are. `many` ones take `a,b,c`.
    pub const fn positional(id: &'static str, kind: Kind) -> Self {
        Self {
            positional: true,
            required: true,
            ..Self::flag(id, kind)
        }
    }

    /// A flag naming a file to upload, `-` for stdin.
    pub const fn file(id: &'static str) -> Self {
        Self {
            file: true,
            ..Self::flag(id, Kind::String)
        }
    }

    #[must_use]
    pub const fn required(mut self) -> Self {
        self.required = true;
        self
    }

    #[must_use]
    pub const fn many(mut self) -> Self {
        self.many = true;
        self
    }

    #[must_use]
    pub const fn help(mut self, help: &'static str) -> Self {
        self.help = help;
        self
    }

    #[must_use]
    pub const fn values(mut self, values: &'static [&'static str]) -> Self {
        self.values = values;
        self
    }

    #[must_use]
    pub const fn value_name(mut self, name: &'static str) -> Self {
        self.value_name = name;
        self
    }

    #[must_use]
    pub const fn range(mut self, range: &'static str) -> Self {
        self.range = range;
        self
    }

    #[must_use]
    pub const fn default_value(mut self, default: &'static str) -> Self {
        self.default = default;
        self
    }

    #[must_use]
    pub const fn deprecated(mut self) -> Self {
        self.deprecated = true;
        self
    }

    pub fn arg(&self) -> Arg {
        let value_name = match (self.positional, self.file) {
            (true, _) => self.id.to_uppercase().replace('-', "_"),
            (_, true) => "FILE".to_owned(),
            _ => value_name(self.kind, self.value_name, self.range),
        };
        let help = match self.file {
            true => format!("{} (a path, or - for stdin)", self.help)
                .trim()
                .to_owned(),
            false => self.help.to_owned(),
        };
        let help = required_help(self.required && !self.positional, self.deprecated, &help);
        let mut arg = Arg::new(self.id)
            .value_name(value_name)
            .required(self.required)
            .action(match self.many && !self.positional {
                true => ArgAction::Append,
                false => ArgAction::Set,
            });
        if !self.positional {
            arg = arg.long(self.id);
        } else if self.many {
            arg = arg.num_args(1).value_delimiter(',');
        }
        let arg = match self.kind {
            Kind::Boolean if self.positional => arg.value_parser(value_parser!(bool)),
            Kind::Boolean => arg
                .num_args(0..=1)
                .require_equals(true)
                .default_missing_value("true")
                .value_parser(value_parser!(bool)),
            Kind::Integer => arg.value_parser(value_parser!(i64)),
            Kind::Number => arg.value_parser(value_parser!(f64)),
            _ => {
                let arg = described(arg, help, self.values);
                return noted(lists(arg, self.kind, self.many, self.values), self.default);
            }
        };
        noted(
            lists(described(arg, help, &[]), self.kind, self.many, &[]),
            self.default,
        )
    }

    /// How errors name it: `--flag` or `<ID>`.
    fn label(id: &str, positional: bool) -> String {
        match positional {
            true => format!("<{}>", id.to_uppercase().replace('-', "_")),
            false => format!("--{id}"),
        }
    }
}

/// The argument of each parameter.
pub fn args(params: &[Param]) -> Vec<Arg> {
    params.iter().map(Param::arg).collect()
}

/// Checks the parameters of the command `key` against the bounds, lengths, patterns and
/// formats of their schemas, for commands whose parameters have some.
pub fn check(ctx: &Ctx, key: &str, matches: &ArgMatches) -> Result<(), CliError> {
    let schema = Schema::parse(ctx.app.schema)?;
    schema.check_params(key, |id| {
        let values = matches.try_get_raw(id).ok().flatten()?;
        Some(values.map(|v| v.to_string_lossy().into_owned()).collect())
    })
}

/// `text` as `T`: as a JSON string first (strings, enums, IDs, dates, decimals), else
/// as JSON (numbers, booleans).
pub fn parse<T: DeserializeOwned>(label: &str, text: &str) -> Result<T, CliError> {
    serde_json::from_value(Value::String(text.to_owned())).or_else(|first| {
        serde_json::from_str(text).map_err(|_| {
            let expected = expected::<T>()
                .map(|hint| format!(" (expected {hint})"))
                .unwrap_or_default();
            CliError::usage(format!(
                "{label}: invalid value `{text}`: {first}{expected}"
            ))
        })
    })
}

/// What a value of `T` looks like, when its type says more than serde's error.
fn expected<T>() -> Option<&'static str> {
    let name = std::any::type_name::<T>();
    let format = match () {
        _ if name.contains("NaiveDateTime") || name.contains("DateTime<") => "date-time",
        _ if name.contains("NaiveDate") => "date",
        _ if name.contains("Uuid") => "uuid",
        _ if name.contains("Decimal") => "decimal",
        _ => return None,
    };
    hint(format)
}

fn texts<'m>(matches: &'m ArgMatches, id: &str) -> Option<impl Iterator<Item = String> + 'm> {
    let values = matches.get_raw(id)?;
    Some(values.map(|value| value.to_string_lossy().into_owned()))
}

/// A flag's value, `None` when not given.
pub fn one<T: DeserializeOwned>(matches: &ArgMatches, id: &str) -> Result<Option<T>, CliError> {
    match texts(matches, id).and_then(Iterator::last) {
        Some(text) => parse(&Param::label(id, false), &text).map(Some),
        None => Ok(None),
    }
}

/// A repeatable flag's values, `None` when not given.
pub fn many<T: DeserializeOwned>(
    matches: &ArgMatches,
    id: &str,
) -> Result<Option<Vec<T>>, CliError> {
    let label = Param::label(id, false);
    texts(matches, id)
        .map(|texts| texts.map(|text| parse(&label, &text)).collect())
        .transpose()
}

/// A required flag's value.
pub fn required<T: DeserializeOwned>(matches: &ArgMatches, id: &str) -> Result<T, CliError> {
    one(matches, id)?.ok_or_else(|| CliError::usage(format!("--{id} is required")))
}

/// A positional argument's value.
pub fn positional<T: DeserializeOwned>(matches: &ArgMatches, id: &str) -> Result<T, CliError> {
    let label = Param::label(id, true);
    let text = texts(matches, id)
        .and_then(|mut texts| texts.next())
        .ok_or_else(|| CliError::usage(format!("{label} is required")))?;
    parse(&label, &text)
}

/// The values of a `many` positional argument, `a,b,c`.
pub fn positionals<T: DeserializeOwned>(
    matches: &ArgMatches,
    id: &str,
) -> Result<Vec<T>, CliError> {
    let label = Param::label(id, true);
    let values: Vec<T> = texts(matches, id)
        .into_iter()
        .flatten()
        .map(|text| parse(&label, &text))
        .collect::<Result<_, _>>()?;
    match values.is_empty() {
        true => Err(CliError::usage(format!("{label} is required"))),
        false => Ok(values),
    }
}

/// Whether the argument was given on the command line.
pub fn given(matches: &ArgMatches, id: &str) -> bool {
    matches.get_raw(id).is_some()
}

/// The files of a repeatable [`Param::file`] flag, `None` when not given.
pub fn files(
    matches: &ArgMatches,
    id: &str,
    stdin: &mut dyn Read,
) -> Result<Option<Vec<File>>, CliError> {
    let Some(paths) = texts(matches, id) else {
        return Ok(None);
    };
    paths
        .map(|path| read(id, &path, stdin))
        .collect::<Result<_, _>>()
        .map(Some)
}

/// `--output`/`-o`, for commands returning a file (`binary`, which needs it) or text.
pub fn output_arg(binary: bool) -> Arg {
    let help = match binary {
        true => "(required) Write the file to FILE, then print {\"path\",\"bytes\",\"content_type\"}; - for stdout",
        false => "Write the response to FILE, then print {\"path\",\"bytes\",\"content_type\"}",
    };
    Arg::new(OUTPUT)
        .long(OUTPUT)
        .short('o')
        .value_name("FILE")
        .help(help)
}

/// Where a file response goes: `--output`, which binary files need (`-` for stdout), unless
/// under `--dry-run`. Checked before the request, so nothing is fetched to be refused.
pub fn output_path(
    ctx: &Ctx,
    matches: &ArgMatches,
    binary: bool,
) -> Result<Option<String>, CliError> {
    match matches.get_one::<String>(OUTPUT) {
        Some(path) if path == "-" => Ok(None),
        Some(path) => Ok(Some(path.clone())),
        None if binary && ctx.dry_run().is_none() => Err(CliError::usage(
            "this command returns a file: pass -o FILE to save it, or -o - to write it to stdout",
        )),
        None => Ok(None),
    }
}

/// A file download, written as its chunks arrive: to `--output` (the file is removed if the
/// download does not finish), else to stdout. Generated code pushes each chunk of the SDK's
/// streamed response, then calls [`finish`](Self::finish).
pub struct Download {
    file: Option<(String, fs::File)>,
    bytes: u64,
    done: bool,
}

impl Download {
    pub fn new(path: Option<&str>) -> Result<Self, CliError> {
        let file = path
            .map(|path| {
                let file = fs::File::create(path).map_err(|error| {
                    CliError::usage(format!("--output: cannot write {path}: {error}"))
                })?;
                Ok::<_, CliError>((path.to_owned(), file))
            })
            .transpose()?;
        Ok(Self {
            file,
            bytes: 0,
            done: false,
        })
    }

    pub fn write(&mut self, ctx: &mut Ctx, chunk: &[u8]) -> Result<(), CliError> {
        self.bytes += chunk.len() as u64;
        match &mut self.file {
            Some((path, file)) => file.write_all(chunk).map_err(|error| {
                CliError::usage(format!("--output: cannot write {path}: {error}"))
            }),
            None => Ok(ctx.out.writer().write_all(chunk)?),
        }
    }

    /// Prints `{path, bytes, content_type}` for a file, or flushes stdout.
    pub fn finish(mut self, ctx: &mut Ctx, content_type: Option<&str>) -> Result<(), CliError> {
        self.done = true;
        match self.file.take() {
            Some((path, file)) => {
                file.sync_all()?;
                let written = serde_json::json!({
                    "path": path,
                    "bytes": self.bytes,
                    "content_type": content_type,
                });
                ctx.print(&written)
            }
            None => Ok(ctx.out.writer().flush()?),
        }
    }
}

impl Drop for Download {
    fn drop(&mut self) {
        if let (false, Some((path, _))) = (self.done, &self.file) {
            let _ = fs::remove_file(path);
        }
    }
}

/// Writes a response that is not JSON, a file or text, to `path` or stdout. Written to a
/// file, `{"path", "bytes", "content_type"}` is printed.
pub fn write_output(
    ctx: &mut Ctx,
    path: Option<&str>,
    bytes: &[u8],
    content_type: Option<&str>,
) -> Result<(), CliError> {
    match path {
        Some(path) => {
            fs::write(path, bytes).map_err(|error| {
                CliError::usage(format!("--output: cannot write {path}: {error}"))
            })?;
            let written = serde_json::json!({
                "path": path,
                "bytes": bytes.len(),
                "content_type": content_type,
            });
            ctx.print(&written)
        }
        None => {
            let out = ctx.out.writer();
            out.write_all(bytes)?;
            out.flush()?;
            Ok(())
        }
    }
}

/// A file to upload, read from the path a flag names or from stdin with `-`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct File {
    pub bytes: Vec<u8>,
    /// The file's name, `None` for stdin.
    pub name: Option<String>,
}

/// The file of a [`Param::file`] flag, `None` when not given.
pub fn file(
    matches: &ArgMatches,
    id: &str,
    stdin: &mut dyn Read,
) -> Result<Option<File>, CliError> {
    match texts(matches, id).and_then(Iterator::last) {
        Some(path) => read(id, &path, stdin).map(Some),
        None => Ok(None),
    }
}

fn read(id: &str, path: &str, stdin: &mut dyn Read) -> Result<File, CliError> {
    let cannot =
        |error: std::io::Error| CliError::usage(format!("--{id}: cannot read {path}: {error}"));
    if path == "-" {
        let mut bytes = Vec::new();
        stdin.read_to_end(&mut bytes).map_err(cannot)?;
        return Ok(File { bytes, name: None });
    }
    let bytes = fs::read(path).map_err(cannot)?;
    let name = std::path::Path::new(path)
        .file_name()
        .map(|name| name.to_string_lossy().into_owned());
    Ok(File { bytes, name })
}

#[cfg(test)]
mod tests {
    use clap::Command;

    use super::*;

    const PARAMS: &[Param] = &[
        Param::positional("id", Kind::String),
        Param::flag("per-page", Kind::Integer).help("Items per page"),
        Param::flag("archived", Kind::Boolean),
        Param::flag("status", Kind::String)
            .values(&["DRAFT", "ACTIVE"])
            .many(),
        Param::file("file"),
        Param::flag("limit", Kind::Integer).required(),
        Param::flag("ids", Kind::Integer).many(),
    ];

    fn matches(given: &[&str]) -> Result<ArgMatches, clap::Error> {
        Command::new("list")
            .args(args(PARAMS))
            .try_get_matches_from(
                ["list"]
                    .into_iter()
                    .chain(given.iter().copied())
                    .chain(["--limit", "1"]),
            )
    }

    #[test]
    fn lists_take_commas_and_numbers_take_a_minus() {
        let m = matches(&[
            "x",
            "--status",
            "DRAFT,ACTIVE",
            "--ids",
            "1,-2",
            "--ids",
            "3",
        ])
        .unwrap();
        assert_eq!(
            many::<String>(&m, "status").unwrap().unwrap(),
            ["DRAFT", "ACTIVE"]
        );
        assert_eq!(many::<i64>(&m, "ids").unwrap().unwrap(), [1, -2, 3]);
        let m = matches(&["x", "--per-page", "-1"]).unwrap();
        assert_eq!(one::<i32>(&m, "per-page").unwrap(), Some(-1));
        let ids = Command::new("get")
            .arg(Param::positional("ids", Kind::Integer).many().arg())
            .try_get_matches_from(["get", "1,2"])
            .unwrap();
        assert_eq!(positionals::<i64>(&ids, "ids").unwrap(), [1, 2]);
    }

    #[test]
    fn help_marks_required_flags() {
        let arg = PARAMS[5].arg();
        assert_eq!(arg.get_help().unwrap().to_string(), "(required)");
        assert_eq!(PARAMS[4].arg().get_value_names().unwrap()[0], "FILE");
    }

    #[test]
    fn help_shows_ranges_defaults_and_deprecation() {
        let arg = Param::flag("per-page", Kind::Integer)
            .help("Items per page")
            .range("1..100")
            .default_value("20")
            .deprecated()
            .arg();
        assert_eq!(arg.get_value_names().unwrap()[0], "INTEGER 1..100");
        assert_eq!(
            arg.get_help().unwrap().to_string(),
            "(deprecated) Items per page [default: 20]"
        );
        let ids = Param::flag("ids", Kind::Integer).many().range(">0").arg();
        assert_eq!(ids.get_value_names().unwrap()[0], "INTEGER >0,...");
    }

    #[test]
    fn dates_say_what_they_expect() {
        #[derive(Debug, serde::Deserialize)]
        struct NaiveDate(#[allow(dead_code)] u8);
        let error = parse::<NaiveDate>("--since", "yesterday").unwrap_err();
        assert!(
            error.message().ends_with("(expected a date, YYYY-MM-DD)"),
            "{error}"
        );
    }

    #[test]
    fn values_are_checked_by_clap_and_typed_by_serde() {
        let m = matches(&[
            "cus_1",
            "--per-page",
            "10",
            "--archived",
            "--status",
            "DRAFT",
            "--status",
            "ACTIVE",
        ])
        .unwrap();
        assert_eq!(positional::<String>(&m, "id").unwrap(), "cus_1");
        assert_eq!(one::<i32>(&m, "per-page").unwrap(), Some(10));
        assert_eq!(one::<bool>(&m, "archived").unwrap(), Some(true));
        assert_eq!(
            many::<String>(&m, "status").unwrap(),
            Some(vec!["DRAFT".to_owned(), "ACTIVE".to_owned()])
        );
        assert_eq!(one::<String>(&m, "file").unwrap(), None);
        let m = matches(&["1", "--archived=false"]).unwrap();
        assert_eq!(one::<bool>(&m, "archived").unwrap(), Some(false));
        assert_eq!(positional::<String>(&m, "id").unwrap(), "1");
        assert_eq!(positional::<u8>(&m, "id").unwrap(), 1);
    }

    #[test]
    fn invalid_values_are_usage_errors_naming_the_argument() {
        assert!(matches(&["x", "--per-page", "ten"]).is_err());
        assert!(matches(&["x", "--status", "GONE"]).is_err());
        let m = matches(&["x", "--per-page", "99999999999"]).unwrap();
        let error = one::<i32>(&m, "per-page").unwrap_err();
        assert_eq!(error.exit_code(), super::super::error::exit::USAGE);
        assert!(
            error
                .message()
                .starts_with("--per-page: invalid value `99999999999`"),
            "{}",
            error.message()
        );
        let error = positional::<u8>(&m, "id").unwrap_err();
        assert!(
            error.message().starts_with("<ID>: invalid value `x`"),
            "{}",
            error.message()
        );
    }

    #[test]
    fn files_are_read_from_a_path_or_stdin() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("logo.png");
        fs::write(&path, b"png").unwrap();
        let m = matches(&["x", "--file", path.to_str().unwrap()]).unwrap();
        let file = file(&m, "file", &mut std::io::empty()).unwrap().unwrap();
        assert_eq!(
            (file.bytes.as_slice(), file.name.as_deref()),
            (&b"png"[..], Some("logo.png"))
        );
        let m = matches(&["x", "--file", "-"]).unwrap();
        let file = super::file(&m, "file", &mut &b"stdin"[..])
            .unwrap()
            .unwrap();
        assert_eq!((file.bytes.as_slice(), file.name), (&b"stdin"[..], None));
        let m = matches(&["x", "--file", "/nonexistent"]).unwrap();
        let error = super::file(&m, "file", &mut std::io::empty()).unwrap_err();
        assert!(error
            .message()
            .starts_with("--file: cannot read /nonexistent"));
    }
}
